#!/usr/bin/env node
/**
 * Upload Workers static assets using a session JWT from assets-upload-session.
 *
 * Prerequisites:
 *   bash scripts/prepare-public.sh   # stages public/{index.html,data.js,assets}
 *
 * Usage:
 *   node scripts/cf-upload-assets.mjs <session.json> [hash-to-path.json]
 *
 * session.json: { jwt, buckets: string[][] }
 *
 * hash-to-path.json (optional): { "<sha256-32hex>": "/abs/or/relative/path", ... }
 * If omitted, the map is generated by walking the staged public/ directory
 * (same SHA-256 truncated to 32 hex chars as the Cloudflare assets manifest).
 *
 * Writes completion JWT to ./kvpose-completion.json (cwd) when done.
 */
import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, '../public');
const accountId = process.env.CLOUDFLARE_ACCOUNT_ID || '4717cdb45968bd12046243c6da6d3b2d';
const sessionPath = process.argv[2];
const hashMapPath = process.argv[3];

if (!sessionPath) {
  console.error('Usage: node scripts/cf-upload-assets.mjs <session.json> [hash-to-path.json]');
  console.error('Run scripts/prepare-public.sh first so public/ is staged.');
  process.exit(1);
}

function mimeFor(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  return {
    '.html': 'text/html; charset=utf-8',
    '.js': 'application/javascript; charset=utf-8',
    '.css': 'text/css; charset=utf-8',
    '.webp': 'image/webp',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.svg': 'image/svg+xml',
    '.json': 'application/json',
    '.woff2': 'font/woff2',
    '.woff': 'font/woff',
  }[ext] || 'application/octet-stream';
}

/** Walk staged assets and build { hash -> absolute path }. Skips dotfiles. */
function buildHashToPath(assetsRoot) {
  if (!fs.existsSync(assetsRoot)) {
    throw new Error(
      `Staged assets directory missing: ${assetsRoot}\n` +
        'Run: bash scripts/prepare-public.sh'
    );
  }
  const map = {};
  function walk(dir) {
    for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
      if (ent.name.startsWith('.')) continue;
      const full = path.join(dir, ent.name);
      const real = fs.realpathSync(full);
      const st = fs.statSync(real);
      if (st.isDirectory()) {
        walk(real);
        continue;
      }
      const buf = fs.readFileSync(real);
      const hash = crypto.createHash('sha256').update(buf).digest('hex').slice(0, 32);
      map[hash] = real;
    }
  }
  walk(assetsRoot);
  return map;
}

function loadHashToPath() {
  if (hashMapPath) {
    if (!fs.existsSync(hashMapPath)) {
      throw new Error(`hash-to-path file not found: ${hashMapPath}`);
    }
    const raw = JSON.parse(fs.readFileSync(hashMapPath, 'utf8'));
    // Resolve relative paths against cwd for portability
    const resolved = {};
    for (const [hash, p] of Object.entries(raw)) {
      resolved[hash] = path.isAbsolute(p) ? p : path.resolve(p);
    }
    console.log(`Loaded hash-to-path map (${Object.keys(resolved).length} entries) from ${hashMapPath}`);
    return resolved;
  }
  const map = buildHashToPath(root);
  console.log(`Generated hash-to-path map (${Object.keys(map).length} entries) from ${root}`);
  return map;
}

const session = JSON.parse(fs.readFileSync(sessionPath, 'utf8'));
if (!session.jwt) {
  throw new Error('session.json must include a jwt field from assets-upload-session');
}
const hashToPath = loadHashToPath();

let completionJwt = session.jwt;
const buckets = session.buckets || [];
console.log(`Uploading ${buckets.length} bucket(s), ${buckets.reduce((n, b) => n + b.length, 0)} files...`);

for (let i = 0; i < buckets.length; i++) {
  const bucket = buckets[i];
  const form = new FormData();
  for (const hash of bucket) {
    const filePath = hashToPath[hash];
    if (!filePath) {
      throw new Error(
        `Missing path for hash ${hash}. ` +
          'Regenerate the map from the same public/ tree used for the upload-session manifest, ' +
          'or pass an explicit hash-to-path.json as the second argument.'
      );
    }
    const b64 = fs.readFileSync(filePath).toString('base64');
    form.append(hash, new Blob([b64], { type: mimeFor(filePath) }));
  }
  const url = `https://api.cloudflare.com/client/v4/accounts/${accountId}/workers/assets/upload?base64=true`;
  process.stdout.write(`  bucket ${i + 1}/${buckets.length} (${bucket.length} files)... `);
  const res = await fetch(url, {
    method: 'POST',
    headers: { Authorization: `Bearer ${session.jwt}` },
    body: form,
  });
  const text = await res.text();
  let json;
  try {
    json = JSON.parse(text);
  } catch {
    throw new Error(`Bad response ${res.status}: ${text.slice(0, 300)}`);
  }
  if (!res.ok || json.success === false) {
    throw new Error(`Upload failed ${res.status}: ${JSON.stringify(json.errors || json)}`);
  }
  if (json.result?.jwt) completionJwt = json.result.jwt;
  console.log('ok');
}

const outPath = path.resolve('kvpose-completion.json');
fs.writeFileSync(outPath, JSON.stringify({ jwt: completionJwt }, null, 2));
console.log(`Wrote ${outPath}`);
